/**
 * Exo Jacobi-1D driver: mirrors PolyBench/C jacobi-1d.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "jacobi-1d.h"

/* Include the Exo-generated kernel header. */
#include "generated/jacobi-1d/jacobi-1d.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n),
		 DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int i;

  for (i = 0; i < n; i++)
    {
      A[i] = ((DATA_TYPE) i + 2) / n;
      B[i] = ((DATA_TYPE) i + 3) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    {
      if (i % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# Unroll / strip-mine factor for the spatial dimension.
# This is a tuning knob: changing it only affects the generated schedule,
# not the external C ABI of the kernel.
UNROLL_I = 4


@proc
def kernel_jacobi_1d_base(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n] @ DRAM,
    B: DATA_TYPE[n] @ DRAM,
):
    # We update elements 1..n-2 and read neighbors at ±1, so n must be > 2.
    assert n > 2

    for t in seq(0, tsteps):
        # First Jacobi sweep: update B from A.
        for i in seq(1, n - 1):
            B[i] = 0.33333 * (A[i - 1] + A[i] + A[i + 1])

        # Second Jacobi sweep: update A from B (uses three-point stencil on B).
        for i in seq(1, n - 1):
            A[i] = 0.33333 * (B[i - 1] + B[i] + B[i + 1])


# ------------------------
# Scheduling / optimization
# ------------------------

p = kernel_jacobi_1d_base

# 1) Shift both spatial loops so they start at 0.
#    This makes strip-mining simpler and keeps index expressions affine.
#    Original:
#       for i in seq(1, n - 1): ...
#    becomes:
#       for i in seq(0, n - 2): ...
#       with every use of i replaced by (i + 1) inside the loop.
i0 = p.find_loop("i #0")          # first i-loop (B update)
p = shift_loop(p, i0, "0")

i1 = p.find_loop("i #1")          # second i-loop (A update)
p = shift_loop(p, i1, "0")

# 2) Strip-mine and unroll the B-update loop over i.
#    We split i into:
#       i = UNROLL_I * io0 + ii0
#    and then fully unroll the small inner loop ii0 to expose ILP
#    and help the backend auto-vectorize.
i0 = p.find_loop("i #0")
p = divide_loop(p, i0, UNROLL_I, ("io0", "ii0"), tail="guard")

ii0 = p.find_loop("ii0")
p = unroll_loop(p, ii0)

# 3) Strip-mine and unroll the A-update loop over i in the same way.
i1 = p.find_loop("i")             # the only remaining i-loop is the A update
p = divide_loop(p, i1, UNROLL_I, ("io1", "ii1"), tail="guard")

ii1 = p.find_loop("ii1")
p = unroll_loop(p, ii1)

# 4) Parallelize the outer strip-mined spatial loops over io0 and io1.
#    This introduces OpenMP parallel-for pragmas in the generated C code.
io0 = p.find_loop("io0")
p = parallelize_loop(p, io0)

io1 = p.find_loop("io1")
p = parallelize_loop(p, io1)

# 5) Clean up index arithmetic and dead code introduced by the transformations.
p = simplify(p)

# 6) Expose the scheduled kernel under the name expected by the C driver.
kernel_jacobi_1d = rename(p, "kernel_jacobi_1d")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(A, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(B, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 1D views to 1D pointers. */
  kernel_jacobi_1d (/*ctxt=*/NULL,
                    tsteps, n,
                    (DATA_TYPE*)POLYBENCH_ARRAY(A),
                    (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
