from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# -----------------------------------------------------------------------------
# Reference Jacobi-1D kernel
#
# Time-stepping stencil:
#   B[i] = (A[i-1] + A[i] + A[i+1]) / 3
#   A[i] = (B[i-1] + B[i] + B[i+1]) / 3
#
# We write it with 0-based interior indexing (i = 0 .. n-3) so that loop
# transforms like tiling and unrolling are easier, but this is algebraically
# equivalent to the classic 1..n-2 formulation:
#   original: i' in [1, n-2], B[i'] uses A[i'-1..i'+1]
#   here    : i  in [0, n-3], B[i+1] uses A[i..i+2]
# -----------------------------------------------------------------------------
@proc
def kernel_jacobi_1d_base(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n] @ DRAM,
    B: DATA_TYPE[n] @ DRAM,
):
    assert n > 2

    for t in seq(0, tsteps):
        # Update B from A.
        for i in seq(0, n - 2):
            B[i + 1] = 0.33333 * (A[i] + A[i + 1] + A[i + 2])

        # Update A from B.
        for i in seq(0, n - 2):
            A[i + 1] = 0.33333 * (B[i] + B[i + 1] + B[i + 2])


# -----------------------------------------------------------------------------
# Scheduling / optimization
#
# Goals:
#   - Improve ILP and help autovectorization by fully unrolling small tiles
#     along the spatial dimension i.
#   - Expose coarse-grain parallelism by parallelizing the outer i-tiles.
#
# Strategy for each of the two spatial sweeps (B-update and A-update):
#   1. Tile the i-loop with a constant tile size (tile_size).
#      This produces:
#        for io in seq(0, (n-2)/tile_size):
#          for ii in seq(0, tile_size):
#            ...
#      plus a correctly guarded tail loop when (n-2) is not divisible by
#      tile_size (tail="guard").
#   2. Fully unroll the inner tile loop (ii) to turn the tile into straight-line
#      code; this is friendly to the C compiler's vectorizer.
#   3. Parallelize the outer tile loop (io) with OpenMP, since each tile
#      updates disjoint indices in A/B and thus is independent.
# -----------------------------------------------------------------------------

# Start from the reference kernel but give the exported procedure the
# name expected by the C driver: kernel_jacobi_1d.
kernel_jacobi_1d = rename(kernel_jacobi_1d_base, "kernel_jacobi_1d")

# Tile size for the spatial dimension. This is a tuning knob: it controls
# both the granularity of parallel work and the size of the unrolled block.
