# This is the first i-loop in the body of the t-loop.
kernel_jacobi_1d = divide_loop(
    kernel_jacobi_1d,
    "i #0",                # first 'i' loop (B update)
    tile_size,             # tile size along i
    ("io_B", "ii_B"),      # new outer and inner iterators
    tail="guard",          # handle remainder iterations safely
