kernel_jacobi_1d = unroll_loop(kernel_jacobi_1d, "ii_B")

# Parallelize the outer tile loop over i. Each tile writes to a disjoint
# segment of B and reads disjoint segments of A, so there are no loop-carried
# dependences along i.
kernel_jacobi_1d = parallelize_loop(kernel_jacobi_1d, "io_B")


