# After the previous divide, the remaining i-loop in the t-loop body
# (matching "i #0") is the A update.
kernel_jacobi_1d = divide_loop(
    kernel_jacobi_1d,
    "i #0",                # now refers to the A-update loop
    tile_size,
    ("io_A", "ii_A"),
    tail="guard",
)

